CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY, quotation_id TEXT NOT NULL UNIQUE REFERENCES quotations(id), title TEXT NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 200), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','paused','completed','cancelled')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS project_milestones(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), title TEXT NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 200), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','in_progress','completed')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS project_milestones_project ON project_milestones(project_id);
CREATE TRIGGER IF NOT EXISTS project_activation_guard BEFORE INSERT ON projects WHEN NEW.status!='active' OR NOT EXISTS(SELECT 1 FROM quotations q JOIN service_requests r ON r.id=q.request_id JOIN customer_accounts a ON a.client_id=r.client_id WHERE q.id=NEW.quotation_id AND q.status='accepted' AND r.status NOT IN ('cancelled','closed') AND a.status='active' AND q.deposit_minor<=COALESCE((SELECT SUM(amount_minor) FROM payment_records WHERE quotation_id=q.id AND status='verified'),0)) BEGIN SELECT RAISE(ABORT,'Project not eligible'); END;
CREATE TRIGGER IF NOT EXISTS project_status_guard BEFORE UPDATE ON projects WHEN NEW.id!=OLD.id OR NEW.quotation_id!=OLD.quotation_id OR OLD.status IN ('completed','cancelled') OR (NEW.status='completed' AND (NOT EXISTS(SELECT 1 FROM project_milestones WHERE project_id=OLD.id) OR EXISTS(SELECT 1 FROM project_milestones WHERE project_id=OLD.id AND status!='completed'))) BEGIN SELECT RAISE(ABORT,'Invalid project transition'); END;
CREATE TRIGGER IF NOT EXISTS milestone_insert_guard BEFORE INSERT ON project_milestones WHEN NOT EXISTS(SELECT 1 FROM projects WHERE id=NEW.project_id AND status='active') BEGIN SELECT RAISE(ABORT,'Project not active'); END;
CREATE TRIGGER IF NOT EXISTS milestone_update_guard BEFORE UPDATE ON project_milestones WHEN NEW.id!=OLD.id OR NEW.project_id!=OLD.project_id OR NOT EXISTS(SELECT 1 FROM projects WHERE id=OLD.project_id AND status='active') BEGIN SELECT RAISE(ABORT,'Project not active'); END;
